import glob

def test_find_version_references():
    results = {}
    for filename in glob.glob("tests/*.py"):
        with open(filename, "r", encoding="utf-8") as f:
            content = f.read()
            lines = [l for l in content.splitlines() if "--version" in l or "version" in l]
            if lines:
                results[filename] = len(lines)
    assert False, results

