import click
from click.testing import CliRunner

def test_version_option_explicit_version():
    @click.command()
    @click.version_option(version="1.2.3")
    def cli():
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--version"])
    assert result.exit_code == 0
    assert "1.2.3" in result.output

def test_version_option_not_found():
    @click.command()
    @click.version_option(package_name="nonexistent_pkg_xyz_123")
    def cli():
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--version"])
    assert result.exit_code != 0
    assert isinstance(result.exception, RuntimeError)
